Given('a todo titled {string} is being edited', async function (title) {
  if (!this.window) {
    await this.openApp();
  }
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  await new Promise(resolve => setTimeout(resolve, 50));

  // Double-click to enter editing mode
  const todos = this.getTodoElements();
  const todo = todos.find(t => t.querySelector('label').textContent === title);
  expect(todo, `Todo "${title}" not found`).to.exist;
  const label = todo.querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  await new Promise(resolve => setTimeout(resolve, 50));

  // Verify editing mode
  expect(todo.classList.contains('editing'), 'Todo should be in editing mode').to.be.true;
});

