  const editingTodo = this.document.querySelector('.todo-list li.editing');
  expect(editingTodo, 'No todo in editing mode').to.exist;
  const editInput = editingTodo.querySelector('.edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  await new Promise(resolve => setTimeout(resolve, 50));
