  expect(toggleAll.checked, 'Toggle-all should be checked').to.be.true;
});

Then('the toggle-all checkbox is not checked', async function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  expect(toggleAll.checked, 'Toggle-all should not be checked').to.be.false;
});

