  const clearBtn = this.document.querySelector('.clear-completed');
  const style = this.window.getComputedStyle(clearBtn);
  expect(style.display).to.not.equal('none');
});

Then('the {string} todo is in editing mode', async function (title) {
  const todos = this.getTodoElements();
  const todo = todos.find(t => {
