#!/usr/bin/env node
/**
 * Plank-join checker: verifies every @planks(...) and @planks-provisional(...)
 * annotation on production seams matches a current step-definition pattern, and
 * every behaviour-bearing step-definition pattern has a matching plank.
 *
 * Exit 0: join is clean. Exit 1: join failures found.
 */
const fs = require('fs');
const path = require('path');

const IMPL_DIR = path.resolve(__dirname, '..', 'js');
const STEPS_DIR = path.resolve(__dirname, '..', 'features', 'step_definitions');
const SPECS_DIR = path.resolve(__dirname, '..', 'specs');

// --- Collect step-definition patterns ---
function collectPatterns(dir) {
  const patterns = [];
  for (const file of fs.readdirSync(dir)) {
    if (!file.endsWith('.js')) continue;
    const content = fs.readFileSync(path.join(dir, file), 'utf8');
    // Match Given('...', When('...', Then('...' patterns
    const re = /^(?:Given|When|Then)\(\s*['"`]([^'"`]+)['"`]/gm;
    let m;
    while ((m = re.exec(content)) !== null) {
      patterns.push(m[1]);
    }
  }
  return patterns;
}

// --- Collect @captain scenarios ---
function collectCaptainScenarios(dir) {
  const scenarios = [];
  for (const file of fs.readdirSync(dir)) {
    if (!file.endsWith('.feature')) continue;
    const content = fs.readFileSync(path.join(dir, file), 'utf8');
    const lines = content.split('\n');
    let pendingCaptain = false;
    let currentScenario = null;
    let currentIsCaptain = false;
    for (const line of lines) {
      // Track @captain tag on lines before Scenario keyword
      if (line.match(/@captain/)) {
        pendingCaptain = true;
      }
      const scenarioMatch = line.match(/^\s*Scenario:\s+(.+)/);
      if (scenarioMatch) {
        // Flush previous scenario
        if (currentScenario && currentIsCaptain) {
          scenarios.push({ file, name: currentScenario });
        }
        currentScenario = scenarioMatch[1].trim();
        currentIsCaptain = pendingCaptain;
        pendingCaptain = false;
      }
    }
    // Flush last scenario
    if (currentScenario && currentIsCaptain) {
      scenarios.push({ file, name: currentScenario });
    }
  }
  return scenarios;
}

// --- Collect @planks and @planks-provisional from implementation ---
function collectPlanks(dir) {
  const planks = [];
  function walk(d) {
    for (const entry of fs.readdirSync(d, { withFileTypes: true })) {
      if (entry.isDirectory()) {
        walk(path.join(d, entry.name));
      } else if (entry.name.endsWith('.js')) {
        const content = fs.readFileSync(path.join(d, entry.name), 'utf8');
        const lines = content.split('\n');
        for (let i = 0; i < lines.length; i++) {
          const plankMatch = lines[i].match(/@planks\(\s*["']([^"']+)["']\s*\)/);
          if (plankMatch) {
            planks.push({ file: path.relative(process.cwd(), path.join(d, entry.name)), line: i + 1, pattern: plankMatch[1], type: 'planks' });
          }
          const provMatch = lines[i].match(/@planks-provisional\(\s*["']([^"']+)["']\s*\)/);
          if (provMatch) {
            planks.push({ file: path.relative(process.cwd(), path.join(d, entry.name)), line: i + 1, reference: provMatch[1], type: 'provisional' });
          }
        }
      }
    }
  }
  walk(dir);
  return planks;
}

// --- Main ---
const patterns = collectPatterns(STEPS_DIR);
const captainScenarios = collectCaptainScenarios(SPECS_DIR);
const planks = collectPlanks(IMPL_DIR);

const captainRefs = new Set(captainScenarios.map(s => {
  // Build repo-root-relative reference for comparison with @planks-provisional
  return `specs/${s.file}:${s.name}`;
}));
const patternSet = new Set(patterns);

let failures = [];

// Check every @planks against current patterns
for (const p of planks) {
  if (p.type === 'planks') {
    if (!patternSet.has(p.pattern)) {
      failures.push(`STALE_PLANK: ${p.file}:${p.line} @planks("${p.pattern}") matches no current step-definition pattern`);
    }
  } else if (p.type === 'provisional') {
    if (!captainRefs.has(p.reference)) {
      failures.push(`STALE_PROVISIONAL: ${p.file}:${p.line} @planks-provisional("${p.reference}") references a scenario no longer carrying @captain`);
    }
  }
}

// Check every step pattern has a plank (only for non-Given/When/Then keywords - skip data steps)
const plankedPatterns = new Set(planks.filter(p => p.type === 'planks').map(p => p.pattern));
for (const pat of patterns) {
  if (!plankedPatterns.has(pat)) {
    failures.push(`UNPLANKED_STEP: pattern "${pat}" has no matching @planks annotation`);
  }
}

if (failures.length > 0) {
  console.error('Plank-join failures:');
  for (const f of failures) {
    console.error('  ' + f);
  }
  process.exit(1);
} else {
  console.log('Plank join clean: ' + planks.length + ' planks, ' + patterns.length + ' patterns, ' + captainScenarios.length + ' @captain scenarios');
  process.exit(0);
}

